Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 524293; // 1<<19 + 5
int N, K, MOD, maxN, bitCount[MAX_N], F[MAX_N];
int A[20][MAX_N], B[20][MAX_N], C[20][MAX_N];
long long MOD_SQ;
long long TMP[20][MAX_N];
long long FACT[MAX_N], INV_FACT[MAX_N];

long long mod_exp(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

void init_arrays() {
    FACT[0] = 1;
    for (int i = 1; i <= maxN; ++i)
        FACT[i] = FACT[i-1] * i % MOD;
    INV_FACT[maxN] = mod_exp(FACT[maxN], MOD - 2);
    for (int i = maxN - 1; i >= 0; --i)
        INV_FACT[i] = INV_FACT[i+1] * (i+1) % MOD;
}

int next_pow2(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void fwht(int *arr, int len, bool inv = false) {
    static long long buf[MAX_N];
    for (int i = 0; i < len; ++i) buf[i] = arr[i];

    if (inv) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    long long x = buf[i + j], y = buf[i + j + step];
                    buf[i + j + step] = (x - y) % MOD;
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    long long x = buf[i + j], y = buf[i + j + step];
                    buf[i + j + step] = (x + y) % MOD;
                }
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        arr[i] = (int)(buf[i] % MOD);
        if (arr[i] < 0) arr[i] += MOD;
    }
}

inline void mod_sub(long long &x) {
    if (x >= MOD_SQ) x -= MOD_SQ;
}

void convolve() {
    for (int i = 0; i <= 19; ++i) {
        memset(A[i], 0, sizeof(int[maxN + 1]));
        memset(TMP[i], 0, sizeof(long long[maxN + 1]));
    }

    for (int i = 0; i <= maxN; ++i)
        A[bitCount[i]][i] = F[i];

    for (int i = 0; i <= 19; ++i)
        fwht(A[i], maxN + 1);

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= maxN; ++s)
                mod_sub(TMP[q + l][s] += 1LL * A[q][s] * B[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= maxN; ++s)
            C[q][s] = (int)(TMP[q][s] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht(C[i], maxN + 1, true);

    for (int i = 0; i <= maxN; ++i)
        F[i] = C[bitCount[i]][i];
}

void square_B() {
    static int buf[20][MAX_N];
    for (int i = 0; i <= 19; ++i)
        memset(TMP[i], 0, sizeof(long long[maxN + 1]));

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= maxN; ++s)
                mod_sub(TMP[q + l][s] += 1LL * B[q][s] * B[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= maxN; ++s)
            buf[q][s] = (int)(TMP[q][s] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht(buf[i], maxN + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(B[i], 0, sizeof(int[maxN + 1]));

    for (int i = 0; i <= maxN; ++i)
        B[bitCount[i]][i] = buf[bitCount[i]][i];

    for (int i = 0; i <= 19; ++i)
        fwht(B[i], maxN + 1);
}

int main() {
    scanf("%d%d%d", &N, &K, &MOD);
    MOD_SQ = 1LL * MOD * MOD;

    if (N & 1) {
        printf("%lld", mod_exp(K, N));
        return 0;
    }

    F[0] = 1;
    maxN = next_pow2(N + 1) - 1;
    init_arrays();

    for (int i = 0; i <= maxN; ++i)
        bitCount[i] = __builtin_popcount(i);

    for (int i = 0; i <= maxN; ++i)
        B[bitCount[i]][i] = INV_FACT[i];

    for (int i = 0; i <= 19; ++i)
        fwht(B[i], maxN + 1);

    int origK = K;
    while (K) {
        if (K & 1) convolve();
        K >>= 1;
        if (K) square_B();
    }

    printf("%lld", (mod_exp(origK, N) - FACT[N] * F[N] % MOD + MOD) % MOD);
    return 0;
}
